AND tracking_identifier = #{trackingIdentifier}
AND req_trck_cmd_status = #{reqTrckCmdStatus}
AND req_trck_cmd_status in
#{item}
AND req_trck_cmd_time < DATE_ADD(now(3), INTERVAL -30 MINUTE)
ORDER BY request_tracking_id
LIMIT #{start},#{end}

